CREATE TABLE knowledge_status_history(id BIGINT NOT NULL,document_id BIGINT NOT NULL,from_status VARCHAR(24) NULL,to_status VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,operator_id BIGINT NOT NULL,reason VARCHAR(500) NULL,occurred_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_knowledge_history_document_time(document_id,occurred_at),CONSTRAINT fk_knowledge_history_document FOREIGN KEY(document_id) REFERENCES knowledge_document(id) ON DELETE CASCADE);
